window.RP_SESSION={"id":"S-0380ab4405ee","messages":[{"id":"Plane-0004009","time":"2026-09-27T01:16:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…끄어어…”","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004010","time":"2026-09-27T01:16:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 괴력열혈전사 띳띠에게 방으로 옮겨진 후…","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004011","time":"2026-09-27T01:16:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"억지로라도 기상!","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004012","time":"2026-09-27T01:16:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”자면 안돼, 스텔라씨 기다려야지…“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004013","time":"2026-09-27T01:17:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고선 크게 하품을 한 뒤…","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004014","time":"2026-09-27T01:17:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…내가 왜 잤더라?\n\n음, 아무렴 어때~“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004015","time":"2026-09-27T01:17:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"기숙사에서 입는 잠옷을 챙긴 후…","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004016","time":"2026-09-27T01:17:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"투타타타~ 건물을 내려가서~","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004017","time":"2026-09-27T01:19:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"3일 넘게 묵은, 그리고 오늘 저녁 낙타굿간을 만들며 흘린 모래먼지와 땀, 오물들을 샤워하며 씻어냅니다.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004018","time":"2026-09-27T01:20:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아흐, 여이! 좀 살겠는걸~!“\n\n허그는 잠옷으로 갈아입은 후, 샤워실에서 개운한 기분으로 길드 마당을 걸어갑니다.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004019","time":"2026-09-27T01:20:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"옷들은 빨아야할테고… 머리끈도 슬슬 갈아야 할 때에요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004020","time":"2026-09-27T01:21:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"어떻게 옷들을 잘 처리해두고, 4층 들락날락.\n스텔라는 아직 없네요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004021","time":"2026-09-27T01:22:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 머리를 말리기 위해 잠시 머리를 풀어두고-\n\n…낙타들 보러가자~","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004022","time":"2026-09-27T01:24:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"길드 뒤의 마구간 옆, 천막 아래 허성하게나마 지어진 넓직한 낙타굿간으로 향합니다.\n\n…옴니버스 최고!","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004023","time":"2026-09-27T01:25:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"부드럽게 깔린 짚 바닥 위에 두 낙타, 돌리와 도트가 편안히 앉아있습니다.\n그러다가…","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004024","time":"2026-09-27T01:25:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이~ 돌리 도트! 나 왔어~“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004025","time":"2026-09-27T01:28:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이내 허그의 인사를 듣곤 졸린 눈을 한 채 목소리의 주인을 쫓아 고개를 돌리네요.\n\n머리 위로 튀어나온 기다란 앞머리 같은 털이 매력적인 이 아이는 도트.\n온순하게 생겨서는 주둥이 아래로 턱수염이 기다랗게 자란 이 아이는 돌리에요.\n\n아마 허그를 발견하고 먼저 일어선 아이는…","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004026","time":"2026-09-27T01:28:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"푸르릉.\n\n도트군요!","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004027","time":"2026-09-27T01:30:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"의뢰에서 가시 마구가 얹혀진 도적떼의 낙타에게 빗겨 지나가다 상처가 생겼었죠.\n\n혹시나 감염이나 탈진이 생기진 않을까 허그가 좀 더 관심을 기울였어서 일까요? 먼저 일어선 도트는 멋들어진 앞머리를 살랑거리며 천천히 울타리에 붙어서는 고개를 내밀고 허그를 맞이해요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004028","time":"2026-09-27T01:32:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 도트구나. 아픈건 좀 어때? 그때 핫산씨가 약초들을 곧장 빌려줬어서 다행이었지~“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004029","time":"2026-09-27T01:34:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 도트의 기다란 목을 투닥투닥…\n슬쩍 몸을 돌리도록 하며 도트의 앞다리와 옆구리를 살펴봐요.\n\n”음… 딱지가 앉았는걸. 아팠을텐데 잘 버텨줬어, 당분간은 여기서 푹 쉬어.\n장하다…“\n\n어째 허그의 입가엔 유독 미소가 가시질 않으며, 자기도 모르게 다정한 말투가 자꾸만 튀어나오네요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004030","time":"2026-09-27T01:38:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이내 저쪽에서 쉬고있던 돌리도 자리에서 일어나, 허그에게로 걸어오네요.\n반갑다는 듯이 얼굴을 부벼대는데…\n\n…턱수염이 간지러워!\n\n”하하하, 돌리구나~ 둘 다 고생 많았어. 굉장했었지~ 도적떼를 둘 씩이나 무찌르고, 마차에 작살들이 박혀서는 자꾸만 어디론가 끌려가려고 그러고.“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004031","time":"2026-09-27T01:38:00+09:00","room":"Plane","name":"시스템","profile":"","identity":"system","type":"system","body":"리엔 에이라스님이 들어왔습니다.","characters":[]},{"id":"Plane-0004032","time":"2026-09-27T01:38:00+09:00","room":"Plane","name":"안내 봇","profile":"오픈채팅봇","identity":"bot","type":"bot","body":"안녕하세요, RP room IV\n어설픈 용맹 Plane입니다.\n\n이곳은 《운명의 굴레》비참여 공간 입니다.","characters":[]},{"id":"Plane-0004033","time":"2026-09-27T01:39:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그럼, 잭이랑 브랜씨도. 돌리 도트도. 상단 사람들도, 다들 수고가 많았어.”\n\n“…아잇, 간지럽다니깐 그러네, 프하하하!”\n\n허그는 돌리의 수염부터 턱 아래를 몇번씩 쓰다듬어주고, 도트의 멋들어진 머리칼을 헝클어도 봐요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004034","time":"2026-09-27T01:42:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“내가 말이지, 받은 의뢰비 전부로 마구랑 너흴 사버려서 요번주는 술 사먹기도 힘들 것 같단 말이야. 어쩔거냐고, 어쩔거야~”\n\n허그는 장난스럽게 둘의 아랫턱을 북북북-\n\n의뢰동안 매번 손으로 쓰다듬고, 두드리고, 줄을 가한 곳을 틈이 날 때마다 어루만지며 달래주었더니 녀석들은 허그의 손을 그닥 싫어하지는 않는 듯 싶네요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004035","time":"2026-09-27T01:45:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…여이…”\n\n허그는 그러다가 한동안 달빛을 받으며 허그에게 머리를 맡기는 중인 두 낙타들을 멍때리며 바라봅니다.\n\n기다란 속눈썹에, 오랫동안 달려도 끄덕 없을 것 같은 몸뚱이의 근육. 저마다 위 아니면 아래로 튀어나온 매력 포인트들까지…\n\n이야, 허그. 제대로 녀석들에게 빠져버린 것 같아요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004036","time":"2026-09-27T01:47:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“역시, 내 낙타들이면 이정도는 되야지.\n둘다 무지하게 멋들어지는걸, 다시 생각해봐도…\n\n데려오길 잘한 것 같아. 정말로.”","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004037","time":"2026-09-27T01:48:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"투닥투닥-\n\n“…여어~”\n\n푸르릉-\n푸프릉.\n\n허그가 둘의 목을 텁텁- 두드리며 슬쩍 밀어내자 이내 돌리와 도트는 다시 굿간 안으로 슬금슬금 들어갑니다.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004038","time":"2026-09-27T01:48:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…얘네들 먹는건 뭘 먹으려나?\n하하, 역시. 아직 모르는게 산더미란 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004039","time":"2026-09-27T01:49:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”—! 자, 시간이 남는걸 허그.\n이럴 시간에 뭐라도 더 배워보자고, 여이!“\n\n허그가 사냥꾼 일을 내려놓는 그 날까지, 아마 매일매일이 바쁠 것 같네요.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004040","time":"2026-09-27T01:50:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 밤은 깊어져만 갑니다.","characters":["P-6a1a99e98a44"]},{"id":"Plane-0004041","time":"2026-09-27T01:50:00+09:00","room":"Plane","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]}]};
